import{_ as a,H as p,f as t,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语 | 心若有所向往，何惧道阻且长","description":"","frontmatter":{},"headers":[{"level":2,"title":"简单而无用？","slug":"简单而无用","link":"#简单而无用","children":[]},{"level":2,"title":"学以致用","slug":"学以致用","link":"#学以致用","children":[]}],"relativePath":"计算机基础实战课/结束语｜心若有所向往，何惧道阻且长.md","filePath":"计算机基础实战课/结束语｜心若有所向往，何惧道阻且长.md","lastUpdated":1795560006000}'),r={name:"计算机基础实战课/结束语｜心若有所向往，何惧道阻且长.md"};function n(l,e,s,o,_,E){return p(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="结束语-心若有所向往-何惧道阻且长" tabindex="-1">结束语 | 心若有所向往，何惧道阻且长 <a class="header-anchor" href="#结束语-心若有所向往-何惧道阻且长" aria-label="Permalink to &quot;结束语 | 心若有所向往，何惧道阻且长&quot;">​</a></h1><p>你好，我是 LMOS。</p><p>首先恭喜你学完了这门课！在过去的四个多月里，我们从芯片到语言、从内存到应用、从 IO到网络，由上而下地掌握了计算机各个领域的基础核心知识。</p><p>你可能会好奇，为什么我会做这样一门课？其实在此之前，我还有一门《操作系统实战 45讲》，主题是如何实现一个五脏俱全的小型操作系统。我曾经以为这门课的深晦会让它石沉大海，但却出乎意料的异常火爆。</p><p>这让我看到了同学们对操作系统的热爱，但也从很多留言里发现了一个更严重的问题——很多同学的计算机基础不扎实。</p><p>我觉得这也是大环境所致，什么有用学什么、什么来钱用什么、什么能快速产出用什么，这会抽象提炼出一个大大的功利主义。</p><p>比如用 Java 能高速构建各种网络系统，因为 Java 本质上就是提供了各种类和组件。你用这些组件能快速出活，自然不用了解其内部的实现和对底层的依赖，美其名日“站在巨人的肩膀上”。效率提升了，但同时也导致我们对巨人的成长过程不闻不问。殊不知巨人倒下之后，我们将无所适从，就算巨人只是生个病（发生漏洞）带来的损失也不可估量。</p><p>于是我萌生了写计算机基础课程的想法。操作系统是我心中之光，我是乐此不疲的追光者，在我眼中，就算是复杂精密的操作系统，经过一层层分割、拆解，最基础的也是这门课里你学到的内容。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><ul><li>计算机基础实战课 知识地图</li></ul><h2 id="简单而无用" tabindex="-1">简单而无用？ <a class="header-anchor" href="#简单而无用" aria-label="Permalink to &quot;简单而无用？&quot;">​</a></h2><p>不知道你学起来的感受是怎样的？从留言区和课程群的各种评论和反馈来看，这门课学起来还是相对轻松的，单独拎出某个知识点来看，甚至显得简单且无趣。所以你学的时候也许会疑惑，这么简单的知识，究竟有用么？</p><p>“1+1” 简单吗？简单。有用吗？单独存在时好像也没有用，但是它却是数理基础。同样地，计算机基础电路晶体管简单吗？简单，而且单独存在时，作用也非常有限。</p><p>在我看来，基础性的东西，共性就是简单，如此才能形成一个个知识点，便于我们“存储”到大脑中形成记忆。</p><p>以应用开发环节为例，开发一个大型应用的时候，我们都会把应用的功能拆开，形成一个个功能模块，这些功能模块彼此独立，模块之间有共同调用的函数库。模块中还会继续划分成一个个类，类中还会进一步拆分出多个函数。</p><p>当我们把视线聚焦到这些具体函数时，你会发现这些函数就会用上我们所讲的基础性知识，大到建立进程、操作读写设备、文件与网络，小到内存复制、处理字符串，这些“基本动作”是不是很眼熟？</p><p>没错，这些就是基础。而这些基础之下还有更基础的东西，层层下推，无外乎就是 IO、编程语言与内存，最终落到物理芯片这一层。看似无用的基础，它们堆叠、扩展、相互协作，就能形成功能强大的产品。</p><p>“道生一，一生二，二生三，三生万物”，这句话老子在两千多年前就说过。其实越是简单的基础，越能扩展出世间万物，任何领域的基础性知识都是这样的。</p><p>所以对计算机基础知识来说，我们第一步要做的就是广泛吸纳知识，各种基础知识点照单全收，不要管有什么用，收入大脑存起来，就像给自己不停增加各种不同的库函数，这样就做到了“博闻”。</p><h2 id="学以致用" tabindex="-1">学以致用 <a class="header-anchor" href="#学以致用" aria-label="Permalink to &quot;学以致用&quot;">​</a></h2><p>为了摆脱“一学就会，一用就废”的怪圈，把这些零散的基础知识“长久存储”，融会贯通，还需要经历一个重要环节——学以致用。</p><p>只有把知识真正用起来，进入“运行时”，才算真正激活了它们。比如你想用代码读写文件，立马就联想到 open、close、read、write 等函数，想操作网络，你立马就能想到套接字接口。这一切是基于你长期运用这些函数的结果。</p><p>这一点感悟来自我的亲身体会。在自学计算机的道路上，我同样磕磕绊绊，但因为好奇心和兴趣的驱动，脚步虽慢，却未曾停止。</p><p>在看过了很多书籍资料之后，我开始尝试把自己的想法用代码实现出来，在真正的计算机上验证一下。在动手实验的过程里，我才遇到了许多先前只看理论时根本无法想到的问题，技术水平也迅速提升。</p><p>纸上得来终觉浅，绝知此事要躬行。你学会了一种知识，然后将其运用在工作中，感受是不一样的。在这个过程中你会不断对各种知识进行强化，从而加深理解，深入思考背后的理论原理，到一定的程度你就会“悟”，会有一种豁然开朗的感觉，那就是了解真理的感觉，那就是认知升级的时刻。</p><p>一旦认知升级，你脑中的机制，自然就会对已经清楚的知识进行打包，思维体系会继续向上一层，追求新的高度。当你日复一日，年复一年的坚持学而用之，认知体系就会自动的一次又一次的迭代升级，随着每次认知体系的升级，都会增强我们的自信心，提升我们的工作能力。</p><p>当我们知识越来越多，也就越来越接近山顶了。这时，你会真正地体会到“会当凌绝顶，一览众山小”的感觉，悄无声息地步入了高手行列。</p><p>到这里，真的要和你说再见了。虽然课程结束了，但是这些内容会持续存在，你可以时不时地复习一下。如果你遇见了什么问题，也欢迎继续给我留言。</p><p>学习是一辈子的事情，千万别停止学习。道阻且长，行则将至。知行合一，未来可期！</p><p>最后，我很想知道你学习这个专栏的感受。这里我为你准备了一份毕业问卷，题目不多，希望你可以花两分钟填一下。</p>',30)])])}const d=a(r,[["render",n]]);export{c as __pageData,d as default};
